/* The cluster's own styles, co-located with the component.
 *
 * They used to live in one app's `shared-chrome.css`, which
 * made `ListCluster` a design-system component that only rendered correctly
 * inside one app: any other consumer got the markup and none of the layout, and
 * the gallery rendered it bare. A component whose CSS lives in a product is not
 * in the system, it is on loan from it.
 *
 * The parent must be a flex column for `margin-block: auto` to centre anything;
 * `<AdaptiveListPage>` does that for its own wrapper. */
.list-cluster {
  margin-block: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-6);
  width: 100%;
}

/* When there are cards, the CARDS row is the centre anchor (1fr/auto/1fr):
 * title sits just above, actions just below. */
.list-cluster[data-cards] {
  flex: 1;
  margin-block: 0;
  display: grid;
  grid-template-rows: 1fr auto 1fr;
  align-items: stretch;
}

.list-cluster[data-cards] .list-cluster-head {
  align-self: end;
}

.list-cluster[data-cards] .list-cluster-grid {
  align-self: center;
}

.list-cluster[data-cards] .list-cluster-cta {
  align-self: start;
  margin-block-start: var(--space-2);
}

.list-cluster-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-2);
  text-align: center;
}

/* The cluster only renders when it fits → hero type can be large. */
.list-cluster-title {
  margin: 0;
  font-family: var(--font-family-display);
  font-size: var(--font-3xl);
  font-weight: var(--font-weight-light);
  line-height: var(--leading-tight);
  color: var(--foreground);
}

/* Capped to a reading measure. Uncapped it ran the full width of the hero — one 20px sentence
 * stretched across 1100px, which is the widest line of text on any screen in the system and the
 * one nobody can follow to its end. A second product had already capped its own copy of this
 * at 30rem; the block should not have needed each product to discover that. */
.list-cluster-subtitle {
  margin: 0;
  max-inline-size: 34rem;
  font-size: var(--font-lg);
  color: var(--muted-foreground);
  line-height: var(--leading-normal);
}

/* Fixed-cap columns that wrap and stay centred: a partial row centres
 * instead of stretching (the DS document-grid pattern).
 *
 * `display` and `gap` belong here and were missing. The rule set columns on an element that was
 * never told to be a grid, so the class only worked next to a second one the consumer wrote
 * (an app pairs it with its own `.tile-grid`). Anywhere else the tiles stacked at their natural
 * height, flush to the start, touching each other — which is exactly how it landed in the first
 * app that used the class on its own. A grid class that is not a grid is not a class. */
.list-cluster .list-cluster-grid {
  width: 100%;
  display: grid;
  gap: var(--space-4);
  /* `1fr`, never a fixed max: see the page audit's `grid-fills-row` rule. */
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  justify-content: center;
  /* KNOWN, and left alone here on purpose: `justify-content` does nothing while every track is
   * `1fr`, so the sentence above about a partial row centring is not what this delivers — a list
   * of one gets one card stretched across the page. Changing the track function is a behaviour
   * change for the three Workshops lists that already override this rule, so it needs its own
   * pass rather than being smuggled in beside a missing `display`. A consumer that wants the
   * welcome layout's few cards CENTRED lays them out itself, as one product does. */
}

/* Bright actions side by side, centred. The secondary one gets a card fill
 * so it reads on the muted page. */
.list-cluster-cta {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-4);
}

.list-cluster-cta .btn[data-variant="secondary"] {
  background: var(--card);
}

.list-cluster-cta .btn[data-variant="secondary"]:hover {
  background: var(--accent);
}

import './ListCluster.css'
import type { ReactNode, Ref } from 'react'

/* Centered "welcome" list: big title + subtitle, the tile grid, a large CTA
 * under the cards. Shown while everything fits the viewport (useSimpleFit).
 * ONE component for Workshops, Transcripts and Discovery — the three lists
 * must always look and behave the same.
 *
 * Copy: the hero title welcomes and names the product; the subtitle says in
 * one sentence what a first-time reader can do here. This is the one place a
 * line under a title is allowed, and it earns it by being the whole screen. */
export function ListCluster({
  mark,
  title,
  subtitle,
  cta,
  clusterRef,
  children,
}: {
  /** The app's brand mark, above the title. Optional: the ecosystem symbol pattern (a light
   *  standalone glyph per app) was hand-rolled in a product hero because this block had nowhere
   *  to put one, which is how a page template stops being adopted. */
  mark?: ReactNode
  /** ReactNode, like PageHeader's: a welcome title routinely carries the product name in the brand
   *  gradient ("Welcome to <span class=brand-word>Razmova</span>"), and typing this as a string is
   *  what sent the first product that wanted one off to hand-roll its own hero. */
  title: ReactNode
  /** Optional. A title that already says it needs no line under it, and forcing one produced
   *  screens explaining their own heading back to the reader. */
  /* ReactNode, like the title above it: the same word means the same shape
   * everywhere in this system, and a welcome line routinely carries a link or
   * a name in the brand colour. Widened 2026-09-03. */
  subtitle?: ReactNode
  cta: ReactNode
  clusterRef?: Ref<HTMLDivElement>
  children: ReactNode
}) {
  return (
    <div className="list-cluster" data-cards ref={clusterRef}>
      {/* A div, not a <header>: outside a sectioning element `<header>` IS the
          page banner landmark, and this sits on a page that already has one in
          `<PageHeader>`. Two banners is an axe violation and, more to the point,
          a screen reader announcing the same landmark twice. Caught by the
          golden example of <AdaptiveListPage>, which renders both together. */}
      <div className="list-cluster-head">
        {mark}
        <h1 className="list-cluster-title">{title}</h1>
        {subtitle && <p className="list-cluster-subtitle">{subtitle}</p>}
      </div>
      {children}
      <div className="list-cluster-cta">{cta}</div>
    </div>
  )
}
